python3 -c "
from openpyxl import load_workbook
from datetime import date

PATH = '/Users/lendwye/Documents/VSC/aidd_week_04_mcp/practice/agent/homework/vague1/report.xlsx'
wb = load_workbook(PATH)

ws = wb['Задачи']
rows = list(ws.iter_rows(min_row=2, values_only=True))
tasks = [
    {'id': r[0], 'title': r[1], 'priority': r[2], 'due': r[3], 'done': bool(r[4])}
    for r in rows
]

def to_date(v):
    if v is None or v == '':
        return None
    if isinstance(v, date):
        return v
    if isinstance(v, str):
        return date.fromisoformat(v.split(' ')[0])
    if hasattr(v, 'date'):
        return v.date()
    return None

today = date(2026, 11, 10)
expected = {
    'Всего': len(tasks),
    'Выполнено': sum(1 for t in tasks if t['done']),
    'Не выполнено': sum(1 for t in tasks if not t['done']),
    'Просрочено': sum(
        1 for t in tasks
        if not t['done'] and t['due'] is not None
        and to_date(t['due']) is not None
        and to_date(t['due']) < today
    ),
    'Low': 0,
    'Normal': 0,
    'High': 0,
}
for t in tasks:
    expected[t['priority'].capitalize()] += 1

ws2 = wb['Сводка']
pairs = {r[0]: r[1] for r in ws2.iter_rows(min_row=2, values_only=True)}

ok = True
for label, expected_value in expected.items():
    got = pairs[label]
    match = abs(float(got) - float(expected_value)) < 1e-9
    ok &= match
    print(f'{label}: сводка={got} пересчёт={expected_value} {\"OK\" if match else \"MISMATCH\"}')

percent = round(expected['Выполнено'] / expected['Всего'] * 100, 2)
print(f'Процент: сводка={pairs[\"Процент выполненных, %\"]} ожидается={percent}')

print('ВСЁ OK' if ok else 'ОШИБКА РАСЧЁТА')
"
